package instance

import (
	"strings"
	"testing"
)

// While an instance is quiesced only replication, the private socket and the loopback address of kingresd are let in.
func TestHoldRulesKeepOnlyReplicationAndKingresd(t *testing.T) {
	in := strings.Join([]string{
		"# Generated by kingresd.",
		"hostssl replication kingres_standby 10.0.0.2/32 cert map=standby",
		"hostssl all all 10.0.0.2/32 cert map=peer",
		"local   all  " + ServiceRole + "  scram-sha-256",
		"host    all  " + ServiceRole + "  127.0.0.1/32  scram-sha-256",
		"host    all  " + ServiceRole + "  ::1/128  scram-sha-256",
		"local   all  all  peer map=" + IdentMap,
		"hostssl all app 0.0.0.0/0 scram-sha-256",
		"host    all  someone  127.0.0.1/32  scram-sha-256",
	}, "\n") + "\n"
	out := HoldRules(in)
	for _, want := range []string{"replication kingres_standby", "local   all  " + ServiceRole, "127.0.0.1/32", "::1/128", "peer map=" + IdentMap} {
		if !strings.Contains(out, want) {
			t.Errorf("the hold rules lack %q:\n%s", want, out)
		}
	}
	for _, bad := range []string{"10.0.0.2/32 cert map=peer", "app 0.0.0.0/0", "someone"} {
		if strings.Contains(out, bad) {
			t.Errorf("the hold rules still let %q in:\n%s", bad, out)
		}
	}
}
